        email.addValueChangeListener(e -> send.setEnabled(true));
        phone.addValueChangeListener(e -> send.setEnabled(true));
        message.addValueChangeListener(e -> send.setEnabled(true));

        Shortcuts.addShortcutListener(this, this::sendIfEnabled, Key.ENTER);

        grid.addColumn(ContactMessage::name).setHeader("Name");
        grid.addColumn(ContactMessage::email).setHeader("Email");
