+    private void keepEditing() {
+        leaveDialog.close();
+        cancelLeave();
+    }
+
+    private void discardAndLeave() {
+        leaveDialog.close();
+        postponedLeave.proceed();
+    }
+
+    // Without this the browser keeps the navigation pending and ignores the next click on the link
+    private void cancelLeave() {
+        postponedLeave.cancel();
+        postponedLeave = null;
+    }
+
+}
