+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendingShowsNotificationAndListsTheMessage() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Ann");
+        TextFieldElement.getByLabel(page, "Phone").setValue("+358 40 1234567");
+        TextAreaElement.getByLabel(page, "Message").setValue("Please call me");
+
+        ButtonElement.getByText(page, "Send").click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement.get(page).assertCellContent(0, 0, "Browser Ann");
+        GridElement.get(page).assertCellContent(0, 3, "Please call me");
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+        TextAreaElement.getByLabel(page, "Message").assertValue("");
+        ButtonElement.getByText(page, "Send").assertDisabled();
+    }
+
+    @Test
+    void emptyFormShowsErrorsInTheFields() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        TextFieldElement.getByLabel(page, "Name").assertInvalid();
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage(
+                "Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        TextAreaElement.getByLabel(page, "Message").assertInvalid();
+    }
+
+    @Test
+    void invalidEmailIsRejectedInTheBrowser() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Eve");
+        EmailFieldElement.getByLabel(page, "Email").setValue("eve@example");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello");
+
+        ButtonElement.getByText(page, "Send").click();
+
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Enter a valid e-mail address");
+        EmailFieldElement.getByLabel(page, "Email").assertValue("eve@example");
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Enter");
+        EmailFieldElement.getByLabel(page, "Email").setValue("enter@example.com");
+        TextAreaElement.getByLabel(page, "Message").setValue("Sent with Enter");
+
+        TextFieldElement.getByLabel(page, "Name").getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement.get(page).assertCellContent(0, 0, "Browser Enter");
+        ButtonElement.getByText(page, "Send").assertDisabled();
+    }
+
+    @Test
+    void typedTextAsksBeforeLeavingAndKeepEditingKeepsTheForm() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Dan");
+
+        aboutLink().click();
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertClosed();
+        TextFieldElement.getByLabel(page, "Name").assertValue("Browser Dan");
+        assertThat(contactHeading()).isVisible();
+
+        // The navigation was cancelled, so the next click asks again
+        aboutLink().click();
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertOpen();
+    }
+
+    @Test
+    void escapeKeepsTheFormAndTheNextClickAsksAgain() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Fay");
+
+        aboutLink().click();
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertOpen();
+        page.keyboard().press("Escape");
+
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertClosed();
+        assertThat(contactHeading()).isVisible();
+        aboutLink().click();
+        DialogElement.getByHeaderText(page, "Leave without sending?").assertOpen();
+    }
+
+    @Test
+    void discardGoesToTheAboutView() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Gus");
+
+        aboutLink().click();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAnyDialog() {
+        aboutLink().click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        assertThat(page.getByRole(AriaRole.DIALOG)).hasCount(0);
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private Locator contactHeading() {
+        return page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact"));
+    }
+
+}
diff --git a/src/test/java/com/example/contact/ContactViewTest.java b/src/test/java/com/example/contact/ContactViewTest.java
