+package com.example.contact;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingLinkEmptyFormAndGrid() {
+        navigate(ContactView.class);
+
+        assertThat(find(H1.class).single().getText()).isEqualTo("Contact");
+        assertThat(routerLink().getText()).isEqualTo("About");
+        assertThat(name().getValue()).isEmpty();
+        assertThat(email().getValue()).isEmpty();
+        assertThat(phone().getValue()).isEmpty();
+        assertThat(message().getValue()).isEmpty();
+        assertThat(send().isEnabled()).isTrue();
+        assertThat(find(Grid.class).exists()).isTrue();
+    }
+
+    @Test
+    void emptyFormShowsErrorsAndSendsNothing() {
+        navigate(ContactView.class);
+        int sentBefore = test(grid()).size();
+
+        test(send()).click();
+
+        assertError(name(), "Name is required");
+        assertError(email(), "Give an e-mail address or a phone number");
+        assertError(message(), "Message is required");
+        assertThat(phone().isInvalid()).isFalse();
+        assertThat(find(Notification.class).exists()).isFalse();
+        assertThat(test(grid()).size()).isEqualTo(sentBefore);
+    }
+
+    @Test
+    void invalidEmailIsRejectedAndInputIsKept() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example", "", "Hello");
+
+        test(send()).click();
+
+        assertError(email(), "Enter a valid e-mail address");
+        assertThat(name().isInvalid()).isFalse();
+        assertThat(message().isInvalid()).isFalse();
+        assertThat(email().getValue()).isEqualTo("ann@example");
+        assertThat(name().getValue()).isEqualTo("Ann");
+    }
+
+    @Test
+    void messageOver500CharactersIsRejected() {
+        navigate(ContactView.class);
+        fill("Ann", "", "+358 40 1234567", "x".repeat(501));
+
+        test(send()).click();
+
+        assertError(message(), "Message must be at most 500 characters");
+        assertThat(find(Notification.class).exists()).isFalse();
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        fill("Ann", "", "+358 40 1234567", "x".repeat(500));
+
+        test(send()).click();
+
+        assertThat(message().isInvalid()).isFalse();
+        assertThat(cell(0, 3)).hasSize(500);
+    }
+
+    @Test
+    void phoneOnlyMessageIsSentAndTheFormIsCleared() {
+        navigate(ContactView.class);
+        int sentBefore = test(grid()).size();
+        fill("Ann Phone", "", "+358 40 1234567", "Please call me");
+
+        test(send()).click();
+
+        assertThat(test(find(Notification.class).single()).getText()).contains("Message sent");
+        assertThat(test(grid()).size()).isEqualTo(sentBefore + 1);
+        assertThat(cell(0, 0)).isEqualTo("Ann Phone");
+        assertThat(cell(0, 2)).isEqualTo("+358 40 1234567");
+        assertThat(cell(0, 3)).isEqualTo("Please call me");
+        assertThat(name().isEmpty()).isTrue();
+        assertThat(email().isEmpty()).isTrue();
+        assertThat(phone().isEmpty()).isTrue();
+        assertThat(message().isEmpty()).isTrue();
+        assertThat(send().isEnabled()).isFalse();
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterTheNextEdit() {
+        navigate(ContactView.class);
+        fill("Ann", "", "+358 40 1234567", "Hi");
+        test(send()).click();
+        assertThat(send().isEnabled()).isFalse();
+
+        test(name()).setValue("B");
+
+        assertThat(send().isEnabled()).isTrue();
+    }
+
+    @Test
+    void emailOnlyMessageIsSent() {
+        navigate(ContactView.class);
+        int sentBefore = test(grid()).size();
+        fill("Bea", "bea@example.com", "", "Mail only");
+
+        test(send()).click();
+
+        assertThat(test(grid()).size()).isEqualTo(sentBefore + 1);
+        assertThat(cell(0, 1)).isEqualTo("bea@example.com");
+    }
+
+    @Test
+    void newestMessageIsListedFirst() {
+        navigate(ContactView.class);
+        fill("First Sender", "", "111", "one");
+        test(send()).click();
+        fill("Second Sender", "", "222", "two");
+        test(send()).click();
+
+        assertThat(cell(0, 0)).isEqualTo("Second Sender");
+        assertThat(cell(1, 0)).isEqualTo("First Sender");
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        int sentBefore = test(grid()).size();
+        fill("Cy", "cy@example.com", "", "Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertThat(find(Notification.class).exists()).isTrue();
+        assertThat(test(grid()).size()).isEqualTo(sentBefore + 1);
+        assertThat(cell(0, 0)).isEqualTo("Cy");
+        assertThat(send().isEnabled()).isFalse();
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        fill("Dee", "", "333", "Once");
+        test(send()).click();
+        int sentBefore = test(grid()).size();
+
+        fireShortcut(Key.ENTER);
+
+        assertThat(test(grid()).size()).isEqualTo(sentBefore);
+        assertThat(name().isInvalid()).isFalse();
+    }
+
+    @Test
+    void enterDoesNothingOnceTheViewIsLeft() {
+        navigate(ContactView.class);
+        int sentBefore = test(grid()).size();
+        fill("Gus", "", "555", "Left behind");
+        test(routerLink()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+
+        fireShortcut(Key.ENTER);
+
+        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
+        navigate(ContactView.class);
+        assertThat(test(grid()).size()).isEqualTo(sentBefore);
+    }
+
+    @Test
+    void sentMessagesAreListedAgainAfterLeavingAndComingBack() {
+        navigate(ContactView.class);
+        fill("Eve Persist", "", "444", "Remember me");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertThat(cell(0, 0)).isEqualTo("Eve Persist");
+    }
+
+    @Test
+    void typedTextAsksBeforeLeavingAndKeepEditingStaysOnTheView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Dan");
+
+        test(routerLink()).click();
+
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+        Dialog dialog = find(Dialog.class).single();
+        assertThat(test(dialog).isOpen()).isTrue();
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertThat(test(dialog).isOpen()).isFalse();
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+        assertThat(name().getValue()).isEqualTo("Dan");
+
+        test(routerLink()).click();
+
+        assertThat(test(dialog).isOpen()).isTrue();
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+    }
+
+    @Test
+    void escapeKeepsTheViewAndTheNextClickAsksAgain() {
+        navigate(ContactView.class);
+        test(name()).setValue("Fay");
+        test(routerLink()).click();
+        Dialog dialog = find(Dialog.class).single();
+
+        test(dialog).pressEscape();
+
+        assertThat(test(dialog).isOpen()).isFalse();
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+        test(routerLink()).click();
+        assertThat(test(dialog).isOpen()).isTrue();
+    }
+
+    @Test
+    void discardGoesToTheAboutView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Dan");
+        test(routerLink()).click();
+
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
+        assertThat(find(H1.class).single().getText()).isEqualTo("About");
+    }
+
+    @Test
+    void typedTextAlsoAsksBeforeOtherNavigation() {
+        navigate(ContactView.class);
+        test(message()).setValue("Half written");
+
+        // navigate() expects the navigation to succeed, so go through the UI to see the postponed one
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+        assertThat(test(find(Dialog.class).single()).isOpen()).isTrue();
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAnyDialog() {
+        navigate(ContactView.class);
+
+        test(routerLink()).click();
+
+        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
+        assertThat(find(H1.class).single().getText()).isEqualTo("About");
+    }
+
+    private static void assertError(TextFieldBase<?, ?> field, String error) {
+        assertThat(field.isInvalid()).isTrue();
+        assertThat(field.getErrorMessage()).isEqualTo(error);
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(phone()).setValue(phoneValue);
+        test(message()).setValue(messageValue);
+    }
+
+    private String cell(int row, int column) {
+        return test(grid()).getCellText(row, column);
+    }
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    private RouterLink routerLink() {
+        return find(RouterLink.class).withText("About").single();
+    }
+
+}
